{
  "goals": [
    {
      "goalId": "fbecbd60-5db3-51e8-94be-d66b066ffa06",
      "reason": "Gemeinsame Zeit verknüpft gleichförmige Horizontalbewegung und vertikale Bewegung unter konstanter Fallbeschleunigung; vertikale Startrichtung und Start-/Endhöhen bestimmen den tatsächlich durchflogenen Bahnabschnitt. / A shared time links uniform horizontal motion and vertical motion under constant gravitational acceleration; the initial vertical direction and launch/landing heights determine the trajectory segment actually traversed.",
      "profile": {
        "archetype": "representation",
        "expectations": [
          {
            "id": "components",
            "essentialUnderstandingDe": "Der schiefe Wurf lässt sich aus gleichförmiger Horizontalbewegung und vertikaler Bewegung mit Anfangsanteil und genau einer Fallbeschleunigung zusammensetzen; alle Komponenten verwenden dieselbe Zeit.",
            "essentialUnderstandingEn": "Oblique projection can be composed from uniform horizontal motion and vertical motion with an initial component and exactly one gravitational acceleration; all components use the same time.",
            "observablePerformanceDe": "Die lernende Person übersetzt vorgegebene Komponenten- oder Zeitdaten in eine qualitative Flugbahnskizze und erklärt am Scheitel den Unterschied zwischen vertikaler und gesamter Geschwindigkeit.",
            "observablePerformanceEn": "The learner translates supplied component or time data into a qualitative trajectory sketch and explains the difference between vertical and total velocity at the highest point."
          },
          {
            "id": "changed-launch",
            "essentialUnderstandingDe": "Ein vertikaler Startanteil nach oben oder unten verändert den vertikalen Bewegungsbeginn, nicht die konstante horizontale Bewegung. Die Fallbeschleunigung wirkt im idealisierten Modell während des gesamten Flugs konstant nach unten; bei der zulässigen Überlagerung aus waagerechtem Wurf und gleichförmigem vertikalem Zusatzanteil wird sie genau einmal berücksichtigt.",
            "essentialUnderstandingEn": "An upward or downward initial vertical component changes the initial vertical motion, not the constant horizontal motion. In the idealised model, gravitational acceleration acts constantly downward throughout the flight; in the permitted superposition of horizontal projection and a uniform additional vertical contribution, it is included exactly once.",
            "observablePerformanceDe": "Die lernende Person konstruiert für einen geänderten Startanteil eine konsistente qualitative Bahn und begründet, welche bekannten Scheitel-/Symmetrieaussagen für die neue Start- und Endhöhe gelten.",
            "observablePerformanceEn": "The learner constructs a consistent qualitative trajectory for a changed initial component and explains which familiar highest-point/symmetry statements apply to the new initial and final heights."
          }
        ],
        "coverageExpectations": {
          "requiredExpectationIds": [
            "components",
            "changed-launch"
          ],
          "alternativeExpectationGroups": [],
          "minimumIndependentDemonstrations": 2,
          "freshVariationRequired": true,
          "independentTransferRequired": true
        },
        "variationAxes": [
          {
            "id": "vertical-sign",
            "textDe": "Positiver gegenüber negativem vertikalem Startanteil bei gleichem horizontalem Anteil.",
            "textEn": "Positive versus negative initial vertical component at equal horizontal component."
          },
          {
            "id": "height-context",
            "textDe": "Gleiche Start-/Endhöhe gegenüber Abwurf oberhalb des Bodens; typische Symmetrie nicht auf den abgeschnittenen gesamten Flug übertragen.",
            "textEn": "Equal launch/landing height versus launch above the ground; do not transfer typical symmetry to the entire height-truncated flight."
          }
        ],
        "applicationCaseBriefs": [
          {
            "id": "upward-components",
            "taskDemandDe": "Ein ideales Wurfmodell ohne Luftwiderstand gibt für die Zeitpunkte t=0/0,2/0,4/0,6/0,8 s die zugehörigen Positionen (x;y)=(0;0)/(0,6;0,6)/(1,2;0,8)/(1,8;0,6)/(2,4;0) m. Skizziere die typische Bahn mit x und y als Ortskoordinaten und den Zeitpunkten als Beschriftungen an den Bahnpunkten. Erkläre die Bewegungskomponenten, erschließe aus Punktabständen und Bahnform die Richtung der Geschwindigkeit am höchsten Punkt und begründe die dort weiterhin wirkende Fallbeschleunigung; keine trigonometrische Zerlegung ist gefordert.",
            "taskDemandEn": "An ideal projectile model without air resistance gives the corresponding positions (x,y)=(0,0)/(0.6,0.6)/(1.2,0.8)/(1.8,0.6)/(2.4,0) m at times t=0/0.2/0.4/0.6/0.8 s. Sketch the typical trajectory with x and y as position coordinates and the times as labels at the trajectory points. Explain the motion components, infer the direction of velocity at the highest point from the point spacings and trajectory shape, and explain why gravitational acceleration continues to act there; no trigonometric decomposition is required.",
            "expectedPerformanceDe": "Konstruiert eine nach unten gekrümmte, zur gleichen Start-/Endhöhe passende Bahn mit gleich großen horizontalen Wegstrecken in gleichen Zeitintervallen. Kennzeichnet x und y als Ortskoordinaten und die Zeiten an den Bahnpunkten. Erschließt aus Punktabständen und Bahnform die nach rechts gerichtete Geschwindigkeit am Scheitel: Dort ist nur v_y=0, während v_x ungleich null bleibt. Begründet mit der fortdauernden Schwerkraftwirkung, dass die Beschleunigung auch am Scheitel unverändert nach unten gerichtet ist. Verwendet für beide Komponenten dieselben Zeiten.",
            "expectedPerformanceEn": "Construct a downward-curving trajectory consistent with equal launch/landing heights and equal horizontal distances over equal time intervals. Identify x and y as position coordinates and label times at the trajectory points. Infer from point spacings and trajectory shape that velocity at the highest point is directed to the right: only v_y=0, while v_x remains nonzero. Explain, using the continuing action of gravity, why acceleration remains unchanged and directed downward at the highest point. Use the same times for both components.",
            "understandingFocusDe": "Eigenständige Koordination von Tabelle, Geschwindigkeitskomponenten und typischer Bahn statt auswendig gelernter Scheitelbehauptung.",
            "understandingFocusEn": "Independent coordination of a table, velocity components and typical trajectory rather than a memorised claim about the highest point."
          },
          {
            "id": "downward-launch",
            "taskDemandDe": "Ein frischer idealer Wurf startet 2 m über dem Boden mit unverändert nach rechts gerichtetem v_x, aber einem von Anfang an nach unten gerichteten vertikalen Startanteil. Die vertikale Beschleunigung bleibt während des gesamten Flugs konstant nach unten gerichtet. Skizziere qualitativ mit x und y als Ortskoordinaten und Zeitmarkierungen an den Bahnpunkten in gleichen Zeitintervallen. Vergleiche mit dem zuvor nach oben gestarteten Wurf und begründe, welche Scheitel- und Symmetrieaussagen für den tatsächlich durchflogenen Abschnitt gelten; eine Flugzeitrechnung ist nicht verlangt.",
            "taskDemandEn": "A fresh ideal projectile starts 2 m above the ground with unchanged rightward v_x but an initially downward vertical component. Vertical acceleration remains constant and downward throughout the flight. Sketch qualitatively with x and y as position coordinates and time labels at trajectory points separated by equal time intervals. Compare with the previous upward launch and explain which highest-point and symmetry statements apply to the segment actually traversed; no flight-time calculation is required.",
            "expectedPerformanceDe": "Zeichnet eine unmittelbar sinkende, zunehmend steile Bahn mit gleich großen horizontalen Wegstrecken in gleichen Zeitintervallen; x und y sind Ortskoordinaten, die Zeit wird an den Bahnpunkten markiert. Begründet, dass der tatsächlich durchflogene Abschnitt am höchsten Punkt dieses Flugs beginnt und nur den absteigenden Ast enthält. Erklärt damit, warum nach dem Abwurf kein oberhalb des Startpunkts liegender Scheitel auftritt und die Symmetrie eines vollständigen Auf- und Abstiegs zwischen gleicher Start- und Endhöhe für diesen Abschnitt nicht gilt. Beschreibt den schiefen Wurf als waagerechten Wurf plus gleichförmigen vertikalen Zusatzanteil oder als zwei getrennte Komponenten; die während des gesamten Flugs konstant nach unten wirkende Fallbeschleunigung wird in der Überlagerung genau einmal berücksichtigt.",
            "expectedPerformanceEn": "Draw an immediately descending, increasingly steep trajectory with equal horizontal distances over equal time intervals; x and y are position coordinates, and time is marked at the trajectory points. Explain that the segment actually traversed begins at the highest point of this flight and contains only the descending branch. Use this to explain why no highest point above the launch position occurs after release and why the symmetry of a complete ascent and descent between equal launch and landing heights does not apply to this segment. Describe oblique projection as horizontal projection plus a uniform additional vertical contribution, or as two separate components; gravitational acceleration acts constantly downward throughout the flight and is included exactly once in the superposition.",
            "understandingFocusDe": "Echter Vorzeichen-/Höhenwechsel bleibt qualitative Wurfkompetenz; mathematisch zulässige Überlagerung ohne doppelte Fallbeschleunigung.",
            "understandingFocusEn": "A genuine sign/height change remains a qualitative projectile competence; mathematically valid superposition without double gravitational acceleration."
          }
        ]
      }
    }
  ],
  "limitations": []
}
